MG.RouteL.deDE = function() return {
  stations = {
    ["01-1"] = {name="Tal der Prüfungen", tips={{k="交通", text="Folg in Durotar der Hauptstraße nach Süden, betritt das Tal der Prüfungen von Osten und such Kaltunk. Die Anreise steht oben."}, {k="取捨", text="Erledige Verlorene Waffen, Faule Peons und beide Quests im Burning Blade Coven in zwei Runden."}, {k="取捨", text="Schließ zuerst die Wichtelquest Üble Familiare oder Üble Familiare ab und nimm dann bei Zureetha Fargaze Burning Blade Medallion (Medaillon der Burning Blade) an (nur Hexenmeister).", s={{"Schließ zuerst die Wichtelquest Üble Familiare oder Üble Familiare ab und nimm dann bei Zureetha Fargaze Burning Blade Medallion (Medaillon der Burning Blade) an (nur Hexenmeister).", {class={"WARLOCK"}}}}}, {k="提醒", text="Unter Level 6? Töte Scheckiger Eber, Skorpidarbeiter oder Übler Familiar auf dem Weg zu Sen'jin.", s={{"Unter Level 6?"}, {"Töte Scheckiger Eber, Skorpidarbeiter oder Übler Familiar auf dem Weg zu Sen'jin"}}}}, danger={[1]="An der Biegung im Burning Blade Coven kannst du mehrere Üble Familiare auf einmal anlocken. Räum vor dem Aufheben der Spitzhacke den Eingang, damit du einen Rückweg hast."}, grind={[1]={mob="Scheckiger Eber", note="Dichte, meist neutrale normale Mobs. Zieh jeweils einen Feind nördlich vom Tal der Prüfungen für Scharfe Zähne auf den Stufen 1-2."}, [2]={mob="Skorpidarbeiter", note="Viele normale, meist neutrale Gegner nordwestlich vom Höhlenbau. Zieh sie einzeln und erledige dabei Stich des Skorpiden."}, [3]={mob="Übler Familiar", note="Viele normale Gegner am Burning Blade Coven. Am Eingang ziehst du leicht mehrere, kämpfe zuerst am Rand. Farme bis Stufe 6, bevor du das Tal verlässt."}}, supply={[1]={npc="Rarc"}, [2]={npc="Zlagk"}, [3]={npc="Duokna"}}, steps={[1]={npc="Kaltunk", tgt="Kaltunk"}, [2]={hint="Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen."}, [3]={npc="Gornek", tgt="Gornek"}, [4]={npc="'Tal der Prüfungen'-Geschenkgutschein", npcObj=true, tag="Optional, Im Spiel prüfen", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für das Tal der Prüfungen hast. Der Gutschein liegt bei Charakteren der zugehörigen Volksgruppe von Anfang an im Rucksack: Rechtsklick genügt, es gibt keinen Annahmepunkt auf der Karte."}, [5]={hint="Bringt Magga den 'Tal der Prüfungen'-Geschenkgutschein.", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für das Tal der Prüfungen hast."}, [6]={npc="Magga", tgt="Magga", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für das Tal der Prüfungen hast."}, [7]={npc="Gornek", tgt="Gornek"}, [8]={npc="Gornek", tgt="Gornek"}, [9]={hint="Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück."}, [10]={hint="Sammelt 6 zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück."}, [11]={npc="Gornek", tgt="Gornek"}, [12]={npc="Kzan Thornslash", tgt="Kzan Thornslash"}, [13]={npc="Gornek", tgt="Gornek"}, [14]={npc="Galgar", tgt="Galgar"}, [15]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [16]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [17]={text="Räum erst das Starttal und geh dann zur Höhle im Norden"}, [18]={hint="Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau."}, [19]={hint="Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen."}, [20]={hint="Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.", desc="Weck fünf schlafende Peons mit der Keule des Vorarbeiters."}, [21]={hint="Tötet 12 üble Familiare.", desc="Als Hexenmeister folgst du Ruzans Questreihe für den Wichtel. Siehe Klassenquests."}, [22]={npc="Hana'zua", tgt="Hana'zua", tag="Optional"}, [23]={hint="Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", tag="Optional"}, [24]={npc="Hana'zua", tgt="Hana'zua", tag="Optional"}, [25]={npc="Hana'zua", tgt="Hana'zua", tag="Optional"}, [26]={hint="Informiert Gornek beim Höhlenbau über Hana'zuas Notlage.", tag="Optional"}, [27]={npc="Gornek", tgt="Gornek", tag="Optional"}, [28]={npc="Gornek", tgt="Gornek"}, [29]={npc="Galgar", tgt="Galgar"}, [30]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [31]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [32]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [33]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [34]={hint="Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", desc="Hol die Spitzhacke im Burning Blade Coven zusammen mit dem Burning Blade Medallion."}, [35]={hint="Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade.", desc="Such Yarrog Schattenbann in der Höhle und plündere 1 Burning Blade Medallion."}, [36]={npc="Großknecht Thazz'ril", tgt="Großknecht Thazz'ril"}, [37]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [38]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [39]={npc="Verschollenes Tagebuch", npcObj=true, tag="Optional", desc="Das Lost Journal liegt bei Zureetha Fargaze."}, [40]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [41]={hint="Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [42]={npc="Frang", tgt="Frang", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [43]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [44]={hint="Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [45]={npc="Frang", tgt="Frang", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [46]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [47]={hint="Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [48]={npc="Rwag", tgt="Rwag", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [49]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [50]={hint="Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [51]={npc="Rwag", tgt="Rwag", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [52]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [53]={hint="Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [54]={npc="Shikrik", tgt="Shikrik", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [55]={npc="Gornek", tgt="Gornek", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [56]={hint="Sprecht mit Shikrik im Tal der Prüfungen.", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [57]={npc="Shikrik", tgt="Shikrik", desc="Schließe Scharfe Zähne ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [58]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller"}, [59]={hint="Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen."}, [60]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller"}, [61]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [62]={hint="Sucht den Geisterfelsen und trinkt das Erdsapta.", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [63]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [64]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [65]={hint="Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen.", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [66]={npc="Canaga Earthcaller", tgt="Canaga Earthcaller", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [67]={npc="Gornek", tgt="Gornek"}, [68]={hint="Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen."}, [69]={npc="Jen'shan", tgt="Jen'shan"}, [70]={npc="Gornek", tgt="Gornek"}, [71]={hint="Sprecht mit Jen'shan im Tal der Prüfungen."}, [72]={npc="Jen'shan", tgt="Jen'shan"}, [73]={npc="Gornek", tgt="Gornek"}, [74]={hint="Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}, [75]={npc="Nartok", tgt="Nartok"}, [76]={npc="Gornek", tgt="Gornek"}, [77]={hint="Lest die besudelte Tafel und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen."}, [78]={npc="Nartok", tgt="Nartok"}, [79]={npc="Ruzan", tgt="Ruzan", desc="Überspring die Wichtelquest im Tal der Prüfungen, wenn du den Wichtel bereits in Todesend freigeschaltet hast."}, [80]={hint="Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", desc="Überspring die Wichtelquest im Tal der Prüfungen, wenn du den Wichtel bereits in Todesend freigeschaltet hast."}, [81]={npc="Ruzan", tgt="Ruzan", desc="Überspring die Wichtelquest im Tal der Prüfungen, wenn du den Wichtel bereits in Todesend freigeschaltet hast."}, [82]={npc="Ruzan", tgt="Ruzan"}, [83]={hint="Sprecht mit Zureetha Fargaze."}, [84]={npc="Zureetha Fargaze", tgt="Zureetha Fargaze"}, [85]={npc="Gornek", tgt="Gornek", desc="Gib Scharfe Zähne ab, um die Steintafel zu erhalten."}, [86]={hint="Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", desc="Gib Scharfe Zähne ab, um die Steintafel zu erhalten."}, [87]={npc="Ken'jai", tgt="Ken'jai", desc="Gib Scharfe Zähne ab, um die Steintafel zu erhalten."}, [88]={npc="Ken'jai", tgt="Ken'jai"}, [89]={hint="Sprecht mit Tai'jin in Durotar."}, [90]={npc="Tai'jin", tgt="Tai'jin"}, [91]={npc="Gornek", tgt="Gornek", desc="Gib Scharfe Zähne ab und such dann den Magierlehrer auf."}, [92]={hint="Lest das Glyphenpergament und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", desc="Gib Scharfe Zähne ab und such dann den Magierlehrer auf."}, [93]={npc="Mai'ah", tgt="Mai'ah", desc="Gib Scharfe Zähne ab und such dann den Magierlehrer auf."}, [94]={npc="Gornek", tgt="Gornek", desc="Gib Scharfe Zähne ab und such dann den Magierlehrer auf."}, [95]={hint="Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", desc="Gib Scharfe Zähne ab und such dann den Magierlehrer auf."}, [96]={npc="Mai'ah", tgt="Mai'ah", desc="Gib Scharfe Zähne ab und such dann den Magierlehrer auf."}, [97]={text="Verlass das Tal der Prüfungen und folg der Straße nach Sen'jin."}}},
    ["01-2"] = {name="Durotar", nameA="Durotar: {a:367} & {a:362}", shortA="Durotar: {a:367} +", tips={{k="取捨", text="Mach die Quest Neuer Rucksack. Sammle die Segeltuchreste zusammen mit den anderen Zielen in der Burg Tiragarde."}, {k="取捨", text="Gib Vernichtet die Verräter ab, um Aus den Wrackteilen geborgen... freizuschalten. Tu es zusammen mit Ein geistvolles Getränk."}, {k="取捨", text="Heb die Dungeonquestreihe in der Kluft der Schatten für später auf. Nimm Verborgene Feinde (→→) bei Thrall an, wenn du in den Ragefire Chasm willst. Hol das Abzeichen für im nördlichen Lager der Burning Blade."}, {k="提醒", text="Unter Level 12? Mach Sicherung der Linien, Die Knochenhöhle oder die ersten paar Bedrohung von unten-Quests.", s={{"Unter Level 12?"}, {"Mach Sicherung der Linien, Die Knochenhöhle oder die ersten paar Bedrohung von unten-Quests"}}}}, danger={[1]="Die Treppen und Türen in Burg Tiragarde können Matrosen von oben ziehen. Räum zuerst die Außenwand und den Eingang frei.", [2]="Meeresriesen durchstreifen das Naga-Gebiet an der Nordküste. Räum nahe Mobs, bevor du einen ziehst. Zieh dich am Ufer zurück, wenn es brenzlig wird."}, grind={[1]={mob="Marinesoldat von Kul Tiras", note="Dichte normale Mobs bei Burg Tiragarde. In den Fluren ziehst du leicht mehrere, kämpfe zuerst draußen. Sammle nebenbei Segeltuchreste für den neuen Rucksack."}, [2]={mob="Schlachtwache der Grimmhauer", note="Normale Mobs sammeln sich westlich von Klingenhügel. Zieh sie am Lagerrand einzeln heran und achte auf Patrouillen. Passt gut zu Übergriff."}, [3]={mob="Sturmhexe der Staubschwingen", note="Normale Mobs, auch Zauberwirker, tummeln sich im nördlichen Durotar. Zieh sie hinter Deckung einzeln heran. Mach Sicherung der Linien oder farme vor Orgrimmar auf Stufe 12."}}, supply={[1]={npc="Trayexir"}, [2]={npc="Gastwirt Grosk"}, [3]={npc="Wuark"}, [4]={npc="Gastwirt Grosk"}, [5]={npc="Ghrawt"}, [6]={npc="Doras"}}, steps={[1]={npc="Ukor", tgt="Ukor", desc="Such Ukor auf dem Weg vom Tal der Prüfungen nach Sen'jin."}, [2]={hint="Sprecht mit Meister Gadrin in Sen'jin."}, [3]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [4]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [5]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [6]={npc="Meister Vornal", tgt="Meister Vornal"}, [7]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [8]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [9]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [10]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [11]={npc="Xar'Ti", tgt="Xar'Ti"}, [12]={npc="Meister Vornal", tgt="Meister Vornal"}, [13]={npc="Pa'zula", tgt="Pa'zula", tag="Optional", desc="Mach die Quest nur, wenn du die Materialien durch Entzaubern beschaffen kannst."}, [14]={text="Melde dich zuerst in Klingenhügel"}, [15]={hint="Tötet 6 Kammschattenkrabbler und 6 Kammschattenlauerer im Süden von Durotar und berichtet anschließend Gar'tok in Klingenhügel davon."}, [16]={hint="Bringt das Tagebuch zu Brakk in Klingenhügel.", tag="Optional"}, [17]={npc="Brakk", tgt="Brakk", tag="Optional"}, [18]={npc="Brakk", tgt="Brakk", tag="Optional"}, [19]={hint="Setzt Euch an Brakks einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", tag="Optional"}, [20]={npc="Brakk", tgt="Brakk", tag="Optional"}, [21]={npc="Brakk", tgt="Brakk", tag="Optional"}, [22]={npc="Brakk", tgt="Brakk", tag="Optional", desc="Mach die Quest erst, wenn du Kürschnerei gelernt hast. Gib sie in Orgrimmar ab."}, [23]={hint="Sprecht mit Orgnil Soulscar in Klingenhügel."}, [24]={hint="Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel."}, [25]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [26]={npc="Gar'Thok", tgt="Gar'Thok"}, [27]={npc="Gastwirt Grosk", tgt="Gastwirt Grosk"}, [28]={text="Bind in Klingenhügel zuerst deinen Ruhestein bei Gastwirt Grosk (51.51, 41.64)."}, [29]={npc="Gar'Thok", tgt="Gar'Thok"}, [30]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [31]={npc="Koch Torka", tgt="Koch Torka"}, [32]={npc="Gar'Thok", tgt="Gar'Thok"}, [33]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Handgefertigte Ledertasche"}}, [34]={npc="Turroc", tgt="Turroc"}, [35]={npc="Koch Torka", tgt="Koch Torka"}, [36]={hint="Sprecht mit Koch Torka in Klingenhügel, um das Kochen zu erlernen.", tag="Optional"}, [37]={npc="Koch Torka", tgt="Koch Torka", tag="Optional"}, [38]={text="Burg Tiragarde → die Wracks → Kolkarklippe und Die Echoinseln"}, [39]={hint="Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück."}, [40]={hint="Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben."}, [41]={hint="Sammelt die Räuberstreitaxt, den Räuberbogen und den Räuberschild um Burg Tiragarde und bringt sie anschließend zu Turroc in Klingenhügel zurück."}, [42]={npc="Vergilbter Umschlag", npcObj=true, desc="Besiege Lieutenant Benedict und nimm den Schlüssel. Öffne oben die Truhe, um den Vergilbten Umschlag zu erhalten."}, [43]={npc="Ukors verlorener Beutel", npcObj=true, tag="Optional", desc="Starte die Quest nur, wenn du den Rucksack unterwegs findest. Geh südwärts zu Ukor."}, [44]={text="Kehr von Burg Tiragarde zu Klingenhügel zurück. Herd, falls fertig."}, [45]={hint="Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle."}, [46]={npc="Gar'Thok", tgt="Gar'Thok"}, [47]={npc="Gar'Thok", tgt="Gar'Thok"}, [48]={npc="Turroc", tgt="Turroc", desc="Du kannst dieselbe Quest beim Grunzer von Klingenhügel annehmen (53.06, 42.48)."}, [49]={npc="Furl Scornbrow", tgt="Furl Scornbrow", star={"Handgefertigte Ledertasche"}}, [50]={npc="Gar'Thok", tgt="Gar'Thok"}, [51]={npc="Gar'Thok", tgt="Gar'Thok", tag="Optional"}, [52]={hint="Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret."}, [53]={hint="Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt."}, [54]={hint="Bringt den Beutel zu Ukor im Süden von Durotar.", tag="Optional"}, [55]={npc="Ukor", tgt="Ukor", tag="Optional"}, [56]={npc="Meister Vornal", tgt="Meister Vornal"}, [57]={hint="Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden."}, [58]={npc="Pal'juh", tgt="Pal'juh", tag="Optional", desc="Pal'juh befindet sich an der Kolkarklippe. Räum die Straße frei, bevor du mit der Eskorte beginnst."}, [59]={hint="Helft Pal'juh, aus der Kolkarklippe zu entkommen, und berichtet anschließend Meister Vornal in Sen'jin davon.", tag="Optional", desc="Pal'juh befindet sich an der Kolkarklippe. Räum die Straße frei, bevor du mit der Eskorte beginnst."}, [60]={npc="Meister Vornal", tgt="Meister Vornal", tag="Optional", desc="Pal'juh befindet sich an der Kolkarklippe. Räum die Straße frei, bevor du mit der Eskorte beginnst."}, [61]={npc="Lar Prowltusk", tgt="Lar Prowltusk"}, [62]={hint="Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier."}, [63]={hint="Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle."}, [64]={hint="Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln."}, [65]={hint="Besiegt Zalazane."}, [66]={hint="Sammelt 8 vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin."}, [67]={hint="Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin."}, [68]={hint="Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen.", tag="Optional", desc="Hier droppt unter anderem der Anhänger Verhexung. Leuchtende Rückstände erhältst du durch Entzaubern."}, [69]={npc="Vel'rin Fang", tgt="Vel'rin Fang"}, [70]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [71]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [72]={npc="Meister Gadrin", tgt="Meister Gadrin"}, [73]={npc="Xar'Ti", tgt="Xar'Ti"}, [74]={npc="Pa'zula", tgt="Pa'zula", tag="Optional"}, [75]={text="Kehr mit dem Ruhestein nach Klingenhügel zurück oder nimm die Nordstraße."}, [76]={npc="Koch Torka", tgt="Koch Torka"}, [77]={npc="Gar'Thok", tgt="Gar'Thok"}, [78]={text="Westlich von Klingenhügel und nördlich von Durotar"}, [79]={hint="Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer."}, [80]={hint="Koch Torka in Klingenhügel möchte, dass Ihr 8 Kaktusfeigen im Revier der Grimmhauer westlich der Stadt sammelt."}, [81]={npc="Gar'Thok", tgt="Gar'Thok"}, [82]={npc="Koch Torka", tgt="Koch Torka"}, [83]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", desc="Min. Stufe 9."}, [84]={hint="Findet Heglan Shadeeye nördlich von Burg Tiragarde.", desc="Min. Stufe 9."}, [85]={npc="Heglan Shadeeye", tgt="Heglan Shadeeye", desc="Min. Stufe 9."}, [86]={npc="Heglan Shadeeye", tgt="Heglan Shadeeye"}, [87]={hint="Findet Hinweise darauf, was Heglan Shadeeye angegriffen hat."}, [88]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [89]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [90]={hint="Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel."}, [91]={hint="Sammelt 9 Nagastachelflossen ein."}, [92]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [93]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [94]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [95]={hint="Tötet den Meeresriesen an der Nordküste von Durotar und bringt einen Beweis für Euren Erfolg zurück.", tag="Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [96]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar", tag="Optional", desc="Elite-Meeresriese an der Nordküste. Gruppen bilden oder bei Bedarf überspringen."}, [97]={npc="Orgnil Soulscar", tgt="Orgnil Soulscar"}, [98]={hint="Sprecht mit Margoz."}, [99]={npc="Margoz", tgt="Margoz"}, [100]={npc="Margoz", tgt="Margoz"}, [101]={hint="Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder."}, [102]={npc="Margoz", tgt="Margoz"}, [103]={npc="Margoz", tgt="Margoz", tag="Optional"}, [104]={text="Optionale EP-Quests vor Stufe 12"}, [105]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [106]={hint="Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar.", tag="Optional"}, [107]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [108]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [109]={hint="Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen.", tag="Optional"}, [110]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [111]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Optional"}, [112]={hint="Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal.", tag="Optional"}, [113]={npc="Misha Tor'kren", tgt="Misha Tor'kren", tag="Optional"}, [114]={npc="Matte Sturmkugel", npcObj=true, tag="Optional", desc="Nimm die Quest nur an, wenn du die Matte Sturmkugel aufhebst."}, [115]={hint="Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm.", tag="Optional", desc="Nimm die Quest nur an, wenn du die Matte Sturmkugel aufhebst."}, [116]={npc="Rezlak", tgt="Rezlak", tag="Optional", desc="Nimm die Quest nur an, wenn du die Matte Sturmkugel aufhebst."}, [117]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [118]={hint="Bringt 5 geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm.", tag="Optional"}, [119]={npc="Rezlak", tgt="Rezlak", tag="Optional"}, [120]={npc="Halikors Huf", npcObj=true, tag="Optional", desc="Wenn du Halikor findest und besiegen kannst, plündere seinen Huf."}, [121]={text="Abholungen in Orgrimmar und Übergabe im Wegekreuz"}, [122]={text="Hast du Orgrimmar-Quests oder Training, folg der Hauptstraße nach Norden und betritt die Stadt durch das Südtor. Schalte den Flugpunkt bei Doras frei (45.12, 63.89). Gib in der Nähe gleich die nächsten Stadtquests ab."}, [123]={hint="Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle.", tag="Optional"}, [124]={npc="Nazgrel", tgt="Nazgrel", tag="Optional"}, [125]={hint="Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster.", tag="Optional"}, [126]={npc="Neeru Fireblade", tgt="Neeru Fireblade", tag="Optional"}, [127]={hint="Geht nach Orgrimmar und sprecht mit Thuwd, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", tag="Optional"}, [128]={npc="Thuwd", tgt="Thuwd", tag="Optional"}, [129]={hint="Bringt Halikors Huf nach Orgrimmar.", tag="Optional"}, [130]={npc="Kamari", tgt="Kamari", tag="Optional"}, [131]={text="Gib erst die Stadtquests ab, dann nutz den Ruhestein nach Klingenhügel. Hat er Abklingzeit, folg der Hauptstraße in Durotar nach Süden. Bist du nicht in die Stadt gegangen, mach gleich mit dem nächsten Schritt weiter."}, [132]={npc="Takrin Pathseeker", tgt="Takrin Pathseeker", desc="Mindestens Stufe 10. Warte bis etwa Stufe 12, bevor du zum Wegekreuz gehst."}, [133]={hint="Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke."}, [134]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [135]={npc="Kargal Battlescar", tgt="Kargal Battlescar"}, [136]={text="Geh vom Farwatch-Posten nach Westen. Bieg an der T-Kreuzung nach Süden ab und erreiche das Wegekreuz im Brachland."}, [137]={hint="Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen."}, [138]={npc="Sergra Darkthorn", tgt="Sergra Darkthorn"}, [139]={npc="Kaplak", tgt="Kaplak", desc="Einführungsquest für Orcs. Trolle können Die Shattered-Hand direkt bei Therzok annehmen."}, [140]={hint="Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", desc="Einführungsquest für Orcs. Trolle können Die Shattered-Hand direkt bei Therzok annehmen."}, [141]={npc="Therzok", tgt="Therzok", desc="Einführungsquest für Orcs. Trolle können Die Shattered-Hand direkt bei Therzok annehmen."}, [142]={npc="Therzok", tgt="Therzok", desc="Stiehl zuerst Tazans Schlüssel und hol dir dann seine Tasche. Behalte den Schlüssel, du brauchst ihn im nächsten Abschnitt."}, [143]={hint="Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", desc="Stiehl zuerst Tazans Schlüssel und hol dir dann seine Tasche. Behalte den Schlüssel, du brauchst ihn im nächsten Abschnitt."}, [144]={npc="Therzok", tgt="Therzok", desc="Stiehl zuerst Tazans Schlüssel und hol dir dann seine Tasche. Behalte den Schlüssel, du brauchst ihn im nächsten Abschnitt."}, [145]={npc="Therzok", tgt="Therzok", desc="Behalte den Schlüssel und öffne die Tasche erst, wenn Therzok dir Die Shattered-Hand gibt.", star={"Klinge der Geschicklichkeit", {"ROGUE"}}}, [146]={hint="Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", desc="Behalte den Schlüssel und öffne die Tasche erst, wenn Therzok dir Die Shattered-Hand gibt."}, [147]={npc="Therzok", tgt="Therzok", desc="Behalte den Schlüssel und öffne die Tasche erst, wenn Therzok dir Die Shattered-Hand gibt.", star={"Klinge der Geschicklichkeit", {"ROGUE"}}}, [148]={npc="Swart", tgt="Swart", desc="Beginn in Klingenhügel. Die Folgequests von Kranal teilen sich mit der Einführung im Dorf der Bluthufe, siehe Wegekreuz. Eine Kette genügt."}, [149]={hint="Sucht Kranal Fiss im Brachland.", desc="Beginn in Klingenhügel. Die Folgequests von Kranal teilen sich mit der Einführung im Dorf der Bluthufe, siehe Wegekreuz. Eine Kette genügt."}, [150]={npc="Kranal Fiss", tgt="Kranal Fiss", desc="Beginn in Klingenhügel. Die Folgequests von Kranal teilen sich mit der Einführung im Dorf der Bluthufe, siehe Wegekreuz. Eine Kette genügt."}, [151]={npc="Sian'dur", tgt="Sian'dur", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [152]={hint="Sprecht mit Thotar in Klingenhügel.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [153]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [154]={npc="Kali Remik", tgt="Kali Remik", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [155]={hint="Sprecht mit Thotar in Klingenhügel.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [156]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [157]={npc="Kary Thunderhorn", tgt="Kary Thunderhorn", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [158]={hint="Sprecht mit Thotar in Klingenhügel.", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [159]={npc="Thotar", tgt="Thotar", tag="Optional", desc="Wähl eine der drei Einstiegsquests oder hol dir Die Bestie zähmen direkt bei Thotar."}, [160]={npc="Thotar", tgt="Thotar"}, [161]={hint="Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel."}, [162]={npc="Thotar", tgt="Thotar"}, [163]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Das zweite Ziel ist ein Brandungskriecher."}, [164]={hint="Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", desc="Voraussetzung: Die Zähmung der Bestie. Das zweite Ziel ist ein Brandungskriecher."}, [165]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Das zweite Ziel ist ein Brandungskriecher."}, [166]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Zähme als Drittes einen Gepanzerten Skorpid."}, [167]={hint="Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", desc="Voraussetzung: Die Zähmung der Bestie. Zähme als Drittes einen Gepanzerten Skorpid."}, [168]={npc="Thotar", tgt="Thotar", desc="Voraussetzung: Die Zähmung der Bestie. Zähme als Drittes einen Gepanzerten Skorpid."}, [169]={npc="Thotar", tgt="Thotar", desc="Trainier nach dem Zähmen die Haustierfähigkeiten im Tal der Ehre in Orgrimmar."}, [170]={hint="Sprecht mit Ormak Grimshot in Orgrimmar.", desc="Trainier nach dem Zähmen die Haustierfähigkeiten im Tal der Ehre in Orgrimmar."}, [171]={npc="Ormak Grimshot", tgt="Ormak Grimshot", desc="Trainier nach dem Zähmen die Haustierfähigkeiten im Tal der Ehre in Orgrimmar."}, [172]={npc="Ophek", tgt="Ophek", tag="Optional", desc="Du kannst die Einstiegsquest überspringen. Horde-Hexenmeister können diese Quest annehmen."}, [173]={hint="Sprecht mit Gan'rul Bloodeye in Orgrimmar.", tag="Optional", desc="Du kannst die Einstiegsquest überspringen. Horde-Hexenmeister können diese Quest annehmen."}, [174]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", tag="Optional", desc="Du kannst die Einstiegsquest überspringen. Horde-Hexenmeister können diese Quest annehmen."}, [175]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Hol die Steintafel in der Knochenhöhle östlich von Orgrimmar."}, [176]={hint="Holt die Schrifttafel der Verga für Gan'rul Bloodeye in Orgrimmar.", desc="Hol die Steintafel in der Knochenhöhle östlich von Orgrimmar."}, [177]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Hol die Steintafel in der Knochenhöhle östlich von Orgrimmar."}, [178]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Benutze am Beschwörungskreis bei Neeru die Inschrift, besiege den Leerwandler und gib die Quest dann bei Gan'rul ab."}, [179]={hint="Beschwört mit Hilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Bloodeye in Orgrimmar zurück.", desc="Benutze am Beschwörungskreis bei Neeru die Inschrift, besiege den Leerwandler und gib die Quest dann bei Gan'rul ab."}, [180]={npc="Gan'rul Bloodeye", tgt="Gan'rul Bloodeye", desc="Benutze am Beschwörungskreis bei Neeru die Inschrift, besiege den Leerwandler und gib die Quest dann bei Gan'rul ab."}, [181]={npc="Tai'jin", tgt="Tai'jin", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [182]={hint="Findet die Grunzerin Kor'ja und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [183]={npc="Tai'jin", tgt="Tai'jin", desc="Trainiere zuerst Geringes Heilen (Rang 2) und Machtwort: Seelenstärke."}, [184]={npc="Tai'jin", tgt="Tai'jin"}, [185]={hint="Sprecht mit Ur'kyo in Orgrimmar."}, [186]={npc="Ur'kyo", tgt="Ur'kyo"}, [187]={npc="Ur'kyo", tgt="Ur'kyo"}, [188]={hint="Questziele erfüllen."}, [189]={npc="Ur'kyo", tgt="Ur'kyo"}, [190]={npc="Uthel'nay", tgt="Uthel'nay", tag="Optional", desc="Nimm die Quest in Orgrimmar bei Uthel'nay oder in Donnerfels bei Thurston Xane (25.18, 20.96) an. In Sen'jin kannst du Jujuhaufen direkt bei Un'Thuwa annehmen."}, [191]={hint="Sprecht mit Un'thuwa.", tag="Optional", desc="Bist du in Sen'jin, nimm Jujuhaufen direkt bei Un'Thuwa an."}, [192]={npc="Un'Thuwa", tgt="Un'Thuwa", tag="Optional", desc="Bist du in Sen'jin, nimm Jujuhaufen direkt bei Un'Thuwa an."}, [193]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [194]={hint="Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück."}, [195]={npc="Un'Thuwa", tgt="Un'Thuwa"}, [196]={text="Schalte am Wegekreuz den Flugpunkt bei Devrak frei (51.50, 30.34). Du kannst deinen Ruhestein bei Gastwirt Boorand Plainswind binden (51.99, 29.89)."}}},
    ["01-3"] = {name="Camp Narache", tips={{k="交通", text="Kommst du aus einer anderen Startzone? Geh zum Dorf der Bluthufe und folge dann der Straße nach Süden über Red Cloud Mesa bis Camp Narache. Die vollständige Anreise steht oben."}, {k="取捨", text="Führ Ritus der Kraft, Tötet Spitzhauer! und Die Kampfeber in einer Dornrankenklamm-Schleife aus. Akzeptiere Angriff auf Camp Narache, wenn du die Karte plünderst."}, {k="提醒", text="Unter Level 6? Töte Kampfeber oder Stacheleber der Borstennacken am Rand von Dornrankenklamm und gehe dann zu Dorf der Bluthufe.", s={{"Unter Level 6?"}, {"Töte Kampfeber oder Stacheleber der Borstennacken am Rand von Dornrankenklamm und gehe dann zu Dorf der Bluthufe"}}}}, danger={[1]="Die Stachelebern drängen sich an der schmalen Rampe in Dornrankenklamm. Räum die Rampe, bevor du Häuptling Spitzhauer Dornenmantel ziehst. Zieh dich bei Bedarf zur Red Cloud Mesa zurück."}, grind={[1]={mob="Ebenenschreiter", note="Dichte, meist neutrale normale Mobs am südöstlichen Brunnen von Camp Narache. Zieh während Die Jagd beginnt jeweils einen Feind heraus."}, [2]={mob="Bergpuma", note="Dichte, meist neutrale normale Mobs am Südhang von Red Cloud Mesa. Zieh einen Feind nach dem anderen, um die in Die Jagd geht weiter benötigten Felle zu erhalten."}, [3]={mob="Kampfeber der Borstennacken", note="Normale Mobs gruppieren sich unter den Stachelebern der Borstennacken in Dornrankenklamm. Räum zuerst den Rand. Kombiniere es mit Kampfeber und Ritus der Kraft."}}, supply={[1]={npc="Bronk Steelrage"}, [2]={npc="Moodan Sungrain"}, [3]={npc="Kawnie Softbreeze"}}, steps={[1]={npc="Camp Narache-Geschenkgutschein", npcObj=true, tag="Optional, Im Spiel prüfen", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für Camp Narache hast. Der Gutschein liegt bei Charakteren der zugehörigen Volksgruppe von Anfang an im Rucksack: Rechtsklick genügt, es gibt keinen Annahmepunkt auf der Karte."}, [2]={hint="Bringt Vorn Skyseer den 'Camp Narache'-Geschenkgutschein.", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für Camp Narache hast."}, [3]={npc="Vorn Skyseer", tgt="Vorn Skyseer", tag="Optional", desc="Nimm die Quest nur an, wenn du den Geschenkgutschein für Camp Narache hast."}, [4]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [5]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [6]={hint="Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt."}, [7]={hint="Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht."}, [8]={npc="Großmutter Hawkwind", tgt="Großmutter Hawkwind"}, [9]={npc="Großmutter Hawkwind", tgt="Großmutter Hawkwind"}, [10]={hint="Holt eine Wasserkanne vom Wasserbrunnen.", desc="Hol die Wasserkanne aus dem Brunnen neben Großmutter Hawkwind."}, [11]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [12]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [13]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [14]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [15]={npc="Kriegerheldin Windfeather", tgt="Kriegerheldin Windfeather"}, [16]={hint="Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt."}, [17]={hint="Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt."}, [18]={npc="Seher Graytongue", tgt="Seher Graytongue"}, [19]={npc="Seher Graytongue", tgt="Seher Graytongue"}, [20]={npc="Seher Graytongue", tgt="Seher Graytongue", tag="Optional", desc="Bring den Weihrauch innerhalb von 10 Minuten nach Erhalt zum Südostaltar.", star={"Versengter Lederbeutel"}}, [21]={hint="Bringt das glimmende Räucherwerk innerhalb von zehn Minuten zum Schrein von An'she und Mu'sha in den südöstlichen Hügeln, bevor es zu Asche verbrennt.", tag="Optional", desc="Bring den Weihrauch innerhalb von 10 Minuten nach Erhalt zum Südostaltar."}, [22]={npc="Ritualfeuer", npcObj=true, tag="Optional", desc="Bring den Weihrauch innerhalb von 10 Minuten nach Erhalt zum Südostaltar.", star={"Versengter Lederbeutel"}}, [23]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [24]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [25]={hint="Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken."}, [26]={hint="Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa."}, [27]={hint="Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt."}, [28]={npc="Schmutzbefleckte Karte", npcObj=true, tag="Optional", desc="Plündere die schmutzige Karte von Stacheleber der Borstennacken und klicke mit der rechten Maustaste darauf."}, [29]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [30]={npc="Kriegerheldin Windfeather", tgt="Kriegerheldin Windfeather"}, [31]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [32]={hint="Bringt Häuptling Hawkwind im Camp Narache die Angriffspläne der Borstennacken.", tag="Optional"}, [33]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind", tag="Optional"}, [34]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind"}, [35]={npc="Häuptling Hawkwind", tgt="Häuptling Hawkwind", tag="Optional"}, [36]={npc="Antur Fallow", tgt="Antur Fallow", tag="Optional", desc="Nimm die Quest bei Antur Fallow erst an, wenn du westlich am Lager vorbeikommst."}, [37]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [38]={hint="Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache.", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [39]={npc="Harutt Thunderhorn", tgt="Harutt Thunderhorn", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [40]={npc="Grull Hawkwind", tgt="Grull Hawkwind", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [41]={hint="Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache.", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [42]={npc="Meela Dawnstrider", tgt="Meela Dawnstrider", desc="Schließe Die Jagd beginnt ab und nimm dann beim Klassenlehrer die Einstiegsquest an."}, [43]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather"}, [44]={hint="Bringt 2 Dosen Ritualsalbe zu der Seherin Ravenfeather im Camp Narache."}, [45]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather"}, [46]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [47]={hint="Sucht den Kodofels und trinkt das Erdsapta.", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [48]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Trink Sapta, um die Schwache Erdmanifestation sehen zu können."}, [49]={npc="Schwache Erdmanifestation", tgt="Schwache Erdmanifestation", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [50]={hint="Bringt den Rohquarz zu der Seherin Ravenfeather im Camp Narache.", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [51]={npc="Seherin Ravenfeather", tgt="Seherin Ravenfeather", desc="Schließe die Quest ab, um dein Erdtotem zu erhalten."}, [52]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [53]={hint="Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa."}, [54]={npc="Lanka Farshot", tgt="Lanka Farshot"}, [55]={npc="Grull Hawkwind", tgt="Grull Hawkwind"}, [56]={hint="Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache."}, [57]={npc="Gart Mistrunner", tgt="Gart Mistrunner"}, [58]={text="Verlass Red Cloud Mesa und folge der Straße nach Norden bis zum Dorf der Bluthufe."}}},
    ["01-4"] = {name="Mulgore", nameA="Mulgore: {a:222}", tips={{k="取捨", text="Mach Ritus der Sicht (→→), Ritus der Weisheit und Reise nach Thunder Bluff. Am letzten Ziel kannst du den Flugpunkt freischalten."}, {k="取捨", text="Gib jede Brunnenquest ab, bevor du die nächste annimmst (nur Tauren). Überspring ab Stufe 12 die Nebenquests zu den Wildmane-Brunnen (nur Tauren).", s={{"Gib jede Brunnenquest ab, bevor du die nächste annimmst (nur Tauren). Überspring ab Stufe 12 die Nebenquests zu den Wildmane-Brunnen (nur Tauren).", {race={"Tauren"}}}}}, {k="取捨", text="Bei deiner Ankunft in Donnerfels kannst du die Vorquests für Ragefire Chasm annehmen. Hol Die Kraft des Feindes wird auf die Probe gestellt und Die Suche nach dem verloren gegangenen Ranzen bei Rahauro nur, wenn du ins Verlies gehst."}, {k="提醒", text="Brauchst du noch EP für Stufe 12? Bekämpfe Harpyien im nördlichen Mulgore oder geh zu den Roten Steinen oder zur Mine der Venture Company. Die Klassenfreischaltungen für Stufe 10 findest du unten bei den Klassenquests.", s={{"Brauchst du noch EP für Stufe 12?"}, {"Bekämpfe Harpyien im nördlichen Mulgore oder geh zu den Roten Steinen oder zur Mine der Venture Company"}, {"Die Klassenfreischaltungen für Stufe 10 findest du unten bei den Klassenquests"}}}}, danger={[1]="Die Mine der Venture Company zieht Patrouillen und Bergleute gleich mit in den Kampf. Räum zuerst den Rand, nimm das Klemmbrett und verlass den Tunnel."}, grind={[1]={mob="Präriepirscher", note="Verstreute normale Mobs nördlich vom Dorf der Bluthufe. Zieh sie einzeln ins Gras und achte auf Streuner. Sammle nebenbei die Materialien für Mazzranache."}, [2]={mob="Vorsteher der Venture Co.", note="Normale Mobs sammeln sich um die Mine der Venture Company. Zieh von außen an und achte auf Arbeiter und Patrouillen. Kombiniere es mit den Minenquests."}, [3]={mob="Matriarchin der Windfurien", note="Dichte normale Mobs im Harpyienlager im Nordwesten von Mulgore, darunter Zauberwirker. Zieh am Rand entlang, um nicht das ganze Lager zu ziehen. Farme hier, wenn du dich Stufe 12 näherst."}}, supply={[1]={npc="Gastwirt Kauth"}, [2]={npc="Harant Ironbrace"}, [3]={npc="Gastwirt Kauth"}, [4]={npc="Kennah Hawkseye"}, [5]={npc="Tal"}}, steps={[1]={hint="Bringt das Vorratsbündel zu Kaga Wildhoof in der Nähe des Dorfs der Bloodhoof.", tag="Optional"}, [2]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [3]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [4]={hint="Setzt Euch an Kagas einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", tag="Optional"}, [5]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [6]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional"}, [7]={npc="Kaga Wildhoof", tgt="Kaga Wildhoof", tag="Optional", desc="Nimm die Quest erst mit Kürschnerei an. Gib sie ab, sobald deine Fertigkeit für die Quest reicht."}, [8]={hint="Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt."}, [9]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [10]={hint="Bringt das Bündel Felle zu Gastwirt Kauth in Bloodhoof.", tag="Optional"}, [11]={npc="Gastwirt Kauth", tgt="Gastwirt Kauth", tag="Optional"}, [12]={text="Bind deinen Ruhestein zuerst bei Gastwirt Kauth im Dorf der Bluthufe (45.93, 64.16)."}, [13]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [14]={hint="Sprecht in Bloodhoof mit Zarlman Two-Moons."}, [15]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [16]={npc="Zarlman Two-Moons", tgt="Zarlman Two-Moons"}, [17]={npc="Harken Windtotem", tgt="Harken Windtotem"}, [18]={npc="Maur Raincaller", tgt="Maur Raincaller"}, [19]={npc="Baine Bloodhoof", tgt="Baine Bloodhoof"}, [20]={npc="Kriegerheld Wildrunner", tgt="Kriegerheld Wildrunner"}, [21]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [22]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Optional"}, [23]={hint="Besiegt 3 andere Spielercharaktere in Duellen oder Novizenkrieger für Tang Stonehoof.", tag="Optional"}, [24]={npc="Krang Stonehoof", tgt="Krang Stonehoof", tag="Optional"}, [25]={npc="Ahab Wheathoof", tgt="Ahab Wheathoof", tag="Optional"}, [26]={hint="Sprecht mit Pyall Silentstride im Dorf der Bloodhoof, um das Kochen zu erlernen.", tag="Optional"}, [27]={npc="Pyall Silentstride", tgt="Pyall Silentstride", tag="Optional"}, [28]={hint="Geht zum Dorf der Bloodhoof und sprecht mit Yonn Deepcut, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", tag="Optional"}, [29]={npc="Yonn Deepcut", tgt="Yonn Deepcut", tag="Optional"}, [30]={text="Östlich von Dorf der Bluthufe → Karawane und Zentauren"}, [31]={hint="Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof."}, [32]={hint="Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele."}, [33]={hint="Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers."}, [34]={hint="Bringt Mull Thunderhorn in Bloodhoof 6 Präriewolftatzen und 4 Ebenenschreiterkrallen."}, [35]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [36]={npc="Mull Thunderhorn", tgt="Mull Thunderhorn"}, [37]={hint="Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück."}, [38]={hint="Findet Langläuferin Malah Longwind östlich des Dorfes der Bloodhoof, nahe Mulgore."}, [39]={npc="Malah Longwind", tgt="Malah Longwind"}, [40]={npc="Malah Longwind", tgt="Malah Longwind"}, [41]={npc="Morin Cloudstalker", tgt="Morin Cloudstalker"}, [42]={hint="Morin Cloudstalker möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht."}, [43]={npc="Versiegelte Vorratskiste", npcObj=true}, [44]={npc="Versiegelte Vorratskiste", npcObj=true}, [45]={hint="Bringt Morin Cloudstalker in der Nähe von Bloodhoof die Dokumente 