    [1791] = {n="Der Windbehüter", d="Sprecht mit Bath'rah dem Windbehüter."},
    [1792] = {n="Wirbelwaffe", star={"Wirbelaxt / Wirbelschwert / Wirbelkriegshammer"}},
    [1795] = {n="Die Bindung", d="Beschwört mit Hilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratchet zurück.", tgo={{"Beschworener Teufelsjäger"}}},
    [1796] = {n="Komponenten für die verzauberte Goldblutrobe", d="Bringt die Roben von Arcana zu Menara Voidrender im Brachland."},
