    [1805] = {n="Foliant der Kabale", d="Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratchet.", tgo={{"Schattenwärter der Dragonmaw", "Knochenwärter der Dragonmaw"}}},
