    [1846] = {n="Schienbeinknochen der Dragonmaw", d="Bringt 8 stabile Schienbeinknochen eines Dragonmaw zu Velora Nitely in Undercity.", tgo={{"Räuber der Dragonmaw", "Sumpfläufer der Dragonmaw", "Zenturio der Dragonmaw", "Schattenwärter der Dragonmaw", "Knochenwärter der Dragonmaw"}}},
