    [1858] = {n="Die Shattered-Hand", d="Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", star={"Klinge der Geschicklichkeit", {"ROGUE"}}},
    [1859] = {n="Therzok", d="Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar."},
