    [1885] = {n="Mennet Carkad", d="Sprecht mit Mennet Carkad im Schurkenviertel von Undercity."},
    [1886] = {n="Die Todespirscher", d="Beschafft Astors Empfehlungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", tgo={{"Astor Hadren"}}},
    [1898] = {n="Die Todespirscher", d="Sprecht mit Andron Gant in Undercity."},
    [1899] = {n="Die Todespirscher", d="Bringt Astors Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Undercity.", objs={"Androns Bücherregal"}},
