    [79442] = {n="Die Waffen des Sturmgewitters", d="Bringt das Auge des Gewittersturms zu Bath'rah dem Windbehüter im Alteracgebirge.", star={"Wut des Sturms / Griff des Blitzschlags / Klaue des Gezeitenbringers"}},
    [80411] = {n="Der Talisman von Kazdor", d="Findet den Talisman von Kazdor in Zul'Farrak. Bringt ihn anschließend zu Fahrad im Ravenholdt-Anwesen. Ihr müsst diese Aufgabe alleine erledigen.", objs={"Verzauberte Kriegstruhe"}},
    [80526] = {n="Schande über mich", d="Sprecht mit Fahrad, wenn Ihr bereit seid, seinen Plan anzuhören."},
