    [92645] = {n="Die Brecherin brechen", d="Tötet Kommandantin Belguilos im Böenbeerentiefland.", tgo={{"Kommandantin Belguilos"}}},
    [92646] = {n="Konfrontiert Lorthuna", d="Nehmt das Portal zu den Türmen der Rohashi oben und schließt Euch Elaadrin Evengale und Ayessa Dawnsinger bei ihrer Konfrontation mit der Hohepriesterin Lorthuna an."},
    [92679] = {n="Blutzoll", d="Hört Euch an, was Alvarion Windfield zu sagen hat, und sucht Aamelia Windfield in Obsthain der Windfields auf.", tgo={{"Aamelia Windfield"}, {"Alvarion Windfield"}}},
    [92682] = {n="Macht Euch nützlich", d="Sammelt 10 reife Sturmäpfel und tötet 5 hungrige Banditen im Obsthain der Windfields.", tgo={{"Hungriger Bandit"}, {}}, objs={"Reifer Sturmapfel"}},
