    [95432] = {n="Erhebt Euch!", d="Rekrutiert 5 Ogerarbeiter."},
    [95454] = {n="Die Ehre der Kor'kron", d="Sucht König Varian Wrynn im Gefängnis von Alcaz."},
    [95483] = {n="Das muss Thrall wissen", d="Gebt Thrall in Orgrimmar Bescheid über Varian Wrynns tragisches Schicksal."},
    [95494] = {n="Verletzter Stolz und Löwenbalg", d="Sammelt 6 Savannenlöwenbälge von den Savannenmatriarchinnen und Savannenpartiarchen im Brachland.", tgo={{"Savannenpatriarch", "Savannenmatriarchin"}}},
    [95495] = {n="Der einsiedlerische Kürschner", d="Bringt das Bündel Bälge dem Einsiedler auf dem Bergkamm über den Trockenen Hügeln im Brachland."},
    [95507] = {n="Vrangs Spiel", d="Sammelt 8 gefangene Wildtiere aus den ausgelösten Fallen im Brachland.", objs={"Ausgelöste Falle"}},
    [95508] = {n="Unwillkommene Gäste", d="Helft Walton, die Begegnung mit Terry Longdrink und der Marine von Kul Tiras zu überleben."},
    [95601] = {n="Die Lilanen", d="Tötet 5 ermächtigte Schläger und 10 Twilight-Ritualisten und kehrt anschließend zu Clubtoe in Sonnengrund zurück.", tgo={{"Machterfüllter Grobian"}, {"Twilight-Ritualist"}}},
    [95602] = {n="Krank machende Lichter", d="Zerstört 5 Twilight-Ritualkreise in den Höhlen unter dem Sonnengrund."},
    [95621] = {n="Ärger im Tal", d="Reist zur verunglückten Karawane und findet heraus, warum die Kul Tiraner hier sind.", tgo={{"Corporal Adamore"}}},
    [95663] = {n="Gerüchte von den Dragonmaw", d="Reist ins Sumpfland und trefft die Todespirscheragentin in den Hügeln über dem Lager der Dragonmaw."},
    [95664] = {n="Wissen der Ältesten", d="Bringt das Relikt der Titanen zur Anhöhe der Ältesten in Thunder Bluff und haltet Ausschau nach jemandem, der Euch mehr darüber erzählen kann."},
    [95682] = {n="Her damit", d="Erledigt die Dragonmawtruppen in der Ausgrabungsstätte und kehrt mit allem, was Ihr dort findet, zur Todespirscheragentin draußen zurück."},
    [95697] = {n="Geschmackswandel", d="Geht zu den Ausgrabungsstätten im Sumpfland und besorgt Dickichtraptorfleisch"},
    [95748] = {n="Die alten Legenden der Gurubashi", d="Verwendet die Haut und die Holzkohle, um ein Abpausbild der dritten Trolllegende anzufertigen.", objs={"Gurubashis Untergang"}},
    [95770] = {n="Die Suche nach der verlorenen Stadt", d="Erkundet das finstere Riff und findet den Höhleneingang."},
    [95773] = {n="Feinde im Wasser", d="Sammelt 10 Laugenschuppendreizacke von Scharmützlern der Laugenschuppen.", tgo={{"Scharmützler der Laugenschuppen"}}},
    [95774] = {n="Ihr Name ist Olgra", d="Erschlagt Stacheleber und sammelt 4 von Olgras Schmuckstücken für Mankriks Denkmal.", tgo={{"Räuber der Grimmhauer"}}},
    [95775] = {n="Die Versunkene Stadt", d="Verwendet die Haut und die Holzkohle, um Abpausbilder der Schrifttafeln in der Versunkenen Stadt anzufertigen."},
    [95776] = {n="...ist eine gute Laugenschuppe", d="Tötet Var'Taka in der Versunkenen Stadt."},
    [95789] = {n="Zwielichtige Salzseher", d="Sammelt 10 voodooerfüllte Artefakte von den Salzseherpiraten in der Versunkenen Stadt."},
    [95791] = {n="Der Kapitän der Salzseher", d="Tötet 3 Leichensammler der Salzseher und Captain Dreadrise in der Versunkenen Stadt."},
    [95803] = {n="Ein Zeichen des guten Glaubens", d="Bringt den Kopf von Rudolph Gelhardt zu Sylvanas Windrunner in Undercity."},
    [95805] = {n="Gunst von An'she und Mu'sha", d="Bringt das glimmende Räucherwerk innerhalb von zehn Minuten zum Schrein von An'she und Mu'sha in den südöstlichen Hügeln, bevor es zu Asche verbrennt.", star={"Versengter Lederbeutel"}},
    [95882] = {n="GESUCHT: Spähmeister Vargas", d="Bringt das Auge des Spähmeisters zu Neza Bloodsnout in Rog'mar.", tgo={{"Spähmeister Vargas"}}},
    [95926] = {n="Der dunkle Kristall", d="Sammelt ein farbloses erschöpftes Kristallfragment in der Nähe des achromatischen Kristalls auf der Terrasse des Formers."},
    [95928] = {n="Kristalline Elemente", d="Bringt Mayena Earthseeker einen feuchten Kristall, einen aufgeladenen Kristall, einen giftigen Kristall und einen feurigen Kristall von der Terrasse des Formers."},
    [95951] = {n="Schnitzen und Stibitzen", d="Sammelt Holzbündel von Arbeiterholzstapeln in Turners Holzfällerlager und schnitzt 20 behelfsmäßige Stechspeere daraus."},
    [95955] = {n="Stecht sie", d="Durchbohrt 10 Süßwasserkrokilisken und kehrt zu Tan'jani in Rog'mar zurück.", tgo={{"Süßwasserkrokilisk"}}},
    [95981] = {n="Straßensperre", d="Tötet 8 Hexer von Dalaran und 8 Behüter von Dalaran für Schattenpriester Allister am Grabmal.", tgo={{"Behüter von Dalaran"}, {"Hexer von Dalaran"}}},
    [96010] = {n="Die Fragmente der Pylonen", d="Bergt Scherben und Fragmente der Pylonen, die in den Dörfern der Magram und der Gelkis bewacht werden, und bringt sie zurück zu Mordent Evenshade."},
    [96018] = {n="Energie für die Pylonen", d="Holt das Manasieb aus dem Tempel in Shen'dralas und verwendet es, um uralte Manakristalle zu sammeln. Ladet die Pylonen auf, sobald Ihr genug Mana gesammelt habt, und kehrt anschließend zu Mordent Evenshade zurück."},
    [96026] = {n="Schritt zwei: Mehr Stein", d="Liefert 10 schwere Gewichtssteine bei Hamur in Bolder'ok ab."},
    [96078] = {n="Eine Geschichte am Feuer", d="Bringt die Abpausbilder der Tafeln Meister Gadrin in im Dorf Sen'jin in Durotar."},
    [96101] = {n="Die große weite Welt", d="Setzt Euch an Raans einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", objs={"Basic Campfire"}},
    [96103] = {n="Ein Schmaus für die Bussarde", d="Bringt den abgeknabberten Schädel zu Neza Bloodsnout in Rog'mar."},
    [96104] = {n="Wenn er fällt, dann Schreiter", d="Bringt einen intakten Weitschreiterschnabel zu Neza Bloodsnout in Rog'mar.", tgo={{"Umherstreifender Weitschreiter"}}},
    [96105] = {n="König der wilden Ebene", d="Verwendet den Weitschreiterruf, um den Anführer des Löwenrudels herbeizurufen. Tötet die Bestie und zieht ihr für Neza Bloodsnout in Rog'mar die Haut ab.", tgo={{"Ombassa"}}},
    [96107] = {n="Federn lassen", d="Bringt Neza Blutschnauze in Rog'mar 6 Präriebussardfedern.", tgo={{"Tiefebenenbussard"}}},
    [96108] = {n="Giftspitzen", d="Bringt 4 Proben Lichtungsviperngift zu Neza Bloodsnout in Rog'mar.", tgo={{"Lichtungsviper"}}},
    [96109] = {n="Köcher machen Jäger", d="Sammelt 6 geschätzte Löwenfelle für Neza Bloodsnout in Rog'mar.", tgo={{"Wildebenenpatriarch", "Wildebenenjägerin"}}},
    [96130] = {n="Chakuyak", d="Besiegt Chakuyak und bringt ihr Fell mit.", tgo={{"Chakuyak"}}},
    [96204] = {n="Der Zorn der Windformerin", d="Begleitet Lumina Windsinger und helft Ihr, Burg Fenris zu entkommen.", tgo={{"Lumina Windsinger"}}},
    [96332] = {n="Ein wenig Vergeltung", d="Begebt Euch in das Gefängnis von Alcaz und tötet 15 Soldaten der Strashaz sowie 8 Verzauberinnen der Strashaz und bringt den Kopf von Gezeitenherrin Ca'zass zu Sergeant Ulka."},
    [96334] = {n="Blutrote Kopftücher", d="Begebt Euch in das Gefängnis von Alcaz und beschafft 8 blutrote Kopftücher von den menschlichen Wachen dort."},
    [96369] = {n="Schlechte Nachrichten für Folkar", d="Meldet Euch bei Kommandant Folkar."},
    [96604] = {n="Die große weite Welt", d="Setzt Euch an Brakks einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", objs={"Basic Campfire"}},
    [96605] = {n="Die große weite Welt", d="Setzt Euch an Kagas einfaches Lagerfeuer und wartet, bis Ihr den verbesserten Ruhebonus erhalten habt.", objs={"Basic Campfire"}},
    [96638] = {n="Der Abenteurer", d="Sprecht mit Raan Wildwind in der Nähe von Shen'dar."},
    [96652] = {n="Der Abenteurer", d="Bringt das Tagebuch zu Brakk in Klingenhügel."},
    [96655] = {n="Grundlagen des Zeltens: Kochen", d="Sprecht mit Koch Torka in Klingenhügel, um das Kochen zu erlernen.", tgo={{"Koch Torka"}}},
    [96659] = {n="Der Abenteurer", d="Bringt das Vorratsbündel zu Kaga Wildhoof in der Nähe des Dorfs der Bloodhoof."},
    [96661] = {n="Grundlagen des Zeltens: Kochen", d="Sprecht mit Pyall Silentstride im Dorf der Bloodhoof, um das Kochen zu erlernen.", tgo={{"Pyall Silentstride"}}},
    [96774] = {n="Uralter Götze der Gurubashi", d="Bergt einen uralten Götzen der Gurubashi aus der Versunkenen Stadt."},
    [96779] = {n="Sabotage des Syndikats", d="Findet Lord Tomas innerhalb der Burg Durnholde im Vorgebirge von Hillsbrad und tötet ihn. Kehrt dann zu Myrokos Silentform zurück.", tgo={{"Lord Tomas"}}},
    [96781] = {n="Was haben sie vor?", d="Entwendet Bartons Späherbericht, indem Ihr ihn von ihm stehlt. Bringt den Bericht dann zu Myrokos Silentform im Ravenholdt-Anwesen.", tgo={{"Barton"}}},
    [96783] = {n="Ein Weg hinein", d="Stehlt eine Uniform des Syndikats aus dem Northfold-Anwesen, um Burg Stromgarde zu infiltrieren."},
    [96784] = {n="Meister der Verkleidung", d="Findet jemanden in Burg Stromgarde, der etwas über den geheimen Handel weiß, während Ihr als ein Mitglied des Syndikats verkleidet seid."},
    [96785] = {n="Wer kann das schon sagen", d="Findet etwas in Burg Stromgarde, das Anastasia davon überzeugen kann, Euch Details über den geheimen Handel zu verraten."},
    [96786] = {n="Der Stich des Syndikats", d="Vereitelt den geheimen Handel und nehmt den Gegenstand, der an das Syndikat verkauft wird, an Euch. Kehrt dann zu Myrokos Silentform im Ravenholdtanwesen zurück."},
    [96821] = {n="Nehmt die Beine in die Hand", d="Tötet 6 Kammschattenkrabbler und 6 Kammschattenlauerer im Süden von Durotar und berichtet anschließend Gar'tok in Klingenhügel davon.", tgo={{"Kammschattenkrabbler"}, {"Kammschattenlauerer"}}},
    [96822] = {n="Für die Ehre", d="Sammelt die Räuberstreitaxt, den Räuberbogen und den Räuberschild um Burg Tiragarde und bringt sie anschließend zu Turroc in Klingenhügel zurück.", objs={"Räuberbogen", "Räuberstreitaxt", "Räuberschild"}},
    [96825] = {n="Diese Frucht beißt zurück", d="Koch Torka in Klingenhügel möchte, dass Ihr 8 Kaktusfeigen im Revier der Grimmhauer westlich der Stadt sammelt.", objs={"Kaktusfeige"}},
    [96873] = {n="Ein Dorn im Nacken", d="Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen."},
    [96876] = {n="Ukors verlorener Beutel", d="Bringt den Beutel zu Ukor im Süden von Durotar."},
    [96877] = {n="Halikors Huf", d="Bringt Halikors Huf nach Orgrimmar."},
    [96895] = {n="Der Argentumabgesandte", d="Findet das Mitglied der Argentumdämmerung in der Nähe des Eingangs von Undercity."},
    [96897] = {n="Der Kult der Verdammten", d="Tötet 8 dunkle Neophyten und 8 dunkle Vollstrecker in Tirisfal.", tgo={{"Dunkler Neophyt"}, {"Dunkler Vollstrecker"}}},
    [96898] = {n="Überreste des Krieges", d="Sammelt 12 nekrotische Kristallfragmente in Tirisfal.", tgo={{"Dunkler Neophyt", "Dunkler Vollstrecker"}}},
    [96899] = {n="Die Bandarionfestung", d="Trefft Leonid Barthalomew in der Bandarionfestung in Tirisfal."},
    [96984] = {n="Das Herz der Störung", d="Holt den Arkanpartikel für Magus Wordeen Voidglare in Tarrens Mühle aus Dalaran."},
    [96986] = {n="Der Grabritter", d="Besiegt Atrexis den Grabritter in Dalaran für Melisara in Tarrens Mühle."},
    [96987] = {n="Opportunistische Bildung", d="Holt das Buch \"Die Gründung von Dalaran\" aus Dalaran für Rexxie Copperclutch in der Nähe des Kanalisationseingangs."},
    [96988] = {n="Quelle der Macht", d="Sammelt 6 gesprungene Wächterkerne in Dalaran für Doktor Martin Felben in Undercity.", objs={"Gespaltener Wachposten"}},
    [97022] = {n="Meldung bei Danitha", d="Sprecht mit Danitha Morr in der Bandarionfestung."},
    [97049] = {n="Essenz sickernder Schleime", d="Sammelt 8 Essenzen des sickernden Schleims auf der Terrasse des Formers."},
    [97196] = {n="Das Auge des Kältebringers", d="Bergt das Auge des Kältebringers in den Hügeln von Razorfen."},
    [97198] = {n="Magie des Schwarzschlunds", d="Bergt ein Ritualtotem des Schwarzschlunds in der Schwarzschlundfeste."},
    [97223] = {n="Blutkrallenmatriarchin", d="Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin.", tgo={{"Blutklauenmatriarchin"}}},
    [97225] = {n="Vergessene Loagötzen", d="Sammelt 8 vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin.", objs={"Vergessener Loagötze"}},
    [97243] = {n="Ruf des Feuers", d="Bringt die Fackel der schlafenden Flamme zu Olariaan Swiftburn im Schrein der Flammen in im Böenbeerentiefland."},
    [97244] = {n="Ruf des Feuers", d="Tötet Himmelspriester Faladiel im Böenbeerentiefland und nehmt Faladiels Herz mit.", tgo={{"Himmelspriester Faladiel"}}},
    [97245] = {n="Ruf des Feuers", d="Findet Kuramaas Zuhause im Shen'darhochland und besiegt den Geist im Kampf. Bringt nach dem Sieg Kuramaas Maske zu Olariaan Swiftburn im Böenbeerentiefland.", tgo={{"Kuramaa"}}},
    [97250] = {n="Falsch verurteilt, angemessen vergolten", d="Tötet Soldaten der Allianz, die an der Grenze zu den Marschen von Dustwallow ins Brachland vordringen, und kehrt anschließend zu Grunzer Logmar ins Camp Taurajo zurück.", tgo={{"Eindringender Soldat"}, {"Erzürnter Plünderer"}}},
    [97253] = {n="Teile und Stücke", d="Sammelt 5 Handvoll komplexer Teile vom oberen Piratenlager südlich von Ratchet und kehrt anschließend zurück zu Wrenix dem Jämmerlichen in Ratchet.", objs={"Haufen komplexer Teile"}},
    [97257] = {n="Ruf des Feuers", d="Wartet, bis Olariaan mit dem Ritual bei der Kohlenpfanne der Opfergabe beginnt, und folgt seinen Anweisungen.\nIhr müsst die Ewige Flamme nach Valanaar bringen, bevor die Zeit abläuft.", tgo={{"Kohlenpfanne der Opfergabe"}, {"Kohlenpfanne der ewigen Flamme"}}, star={"Totem der Geladenen Flammen", {"SHAMAN"}}},
    [97265] = {n="Zürnt den Zornsäern", d="Besiegt eine Auswahl an Satyrn der Zornsäer bei Sargeron in Desolace und kehrt dann zu Aka'rai im Dorf Shadowprey zurück.", tgo={{"Schwindler der Zornsäer"}, {"Höllenrufer der Zornsäer"}, {"Schattenpirscher der Zornsäer"}, {"Teufelsanbeter der Zornsäer"}, {"Schurke der Zornsäer"}}},
    [97279] = {n="Verlorene Waffen", d="Sammelt 6 zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück.", objs={"Zurückgelassene Übungswaffe"}},
    [97281] = {n="Ein Sturm braut sich zusammen", d="Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm."},
    [97282] = {n="Elektrisierende Aussichten", d="Bringt 5 geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm.", tgo={{"Donnerechse", "Blitzechse", "Halikor"}}},
    [97287] = {n="Geschickte Verhandlungen", d="Sprecht mit dem Abbild der Erzmagierin Modera in der Nähe von Dalaran."},
    [97288] = {n="Endlose Qual", d="Bringt den monströsen Kopf zu Apothekermeister Faranell in Undercity."},
    [97289] = {n="Endlose Qual", d="Bringt den Kopf des Barons zu Othmars Leiche in Undercity."},
    [97290] = {n="Endlose Qual", d="Berichtet Apothekermeister Faranell in Undercity von Euren Erkenntnissen."},
    [97291] = {n="Endlose Qual", d="Holt eine giftige Schädelkappe von Tawny Grisette im Handwerksviertel, Blasenkraut in der Nähe des Kräuterkundelehrers und eine Essenz der Pein vom Giftverkäufer im Schurkenviertel für Meisterapotheker Faranell in Undercity.", objs={"Blasenkraut"}},
    [97292] = {n="Endlose Qual", d="Spritzt das zischende Serum für Meisterapotheker Faranell in das System über Othmars Leiche.", objs={"Othmar's Head"}},
    [97327] = {n="Schwarzschlundbeutel", d="Begebt Euch in die Schwarzschlundfeste und bergt 5 Schwarzschlundbeutel für Ekkal an den Ruinen von Eldarath in Azshara.", tgo={{"Berserker des Schwarzschlunds", "Knecht des Schwarzschlunds", "Kopfjäger des Schwarzschlunds", "Schwärmender Wichtel", "Schlächter der Legashi", "Champion des Schwarzschlunds"}}},
    [97328] = {n="Alles von Wert", d="Bergt 8 gestohlene Lieferungen aus den Ruinen von Zul'Kunda im Schlingendorntal und kehrt damit nach Booty Bay zurück."},
    [97329] = {n="Wo ist der Schlüssel?", d="Bringt Zimmix Sputterspark den primitiven Schlüssel, den Ihr von den Trollen in den Runen von Zul'kunda im Schlingendorntal erhalten habt.", tgo={{"Späher der Bloodscalp", "Jäger der Bloodscalp", "Berserker der Bloodscalp", "Hexendoktor der Bloodscalp", "Kopfjäger der Bloodscalp", "Bestienmeister der Bloodscalp", "Mystiker der Bloodscalp"}}},
    [97331] = {n="Zimmix' große Flucht", d="Eskortiert Zimmix Sputterspark fort von den Ruinen von Zul'Kunda und erzählt Werftmeister Lozgil in Booty Bay von Eurer erfolgreichen Rettung."},
    [97332] = {n="Zweimal enttäuschtes Vertrauen", d="Liefert das zweifach wiederbestellte Paket an Werftmeister Whizzbuzz im Hafen von Powderfuse in den Flusslanden."},
    [97386] = {n="Die Offensive von Grom'gol", d="Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr Oger beim Ogerhügel der Mosh'Ogg tötet.", tgo={{"Zauberkundiger der Mosh'Ogg"}, {"Kriegstreiber der Mosh'Ogg"}, {"Raufer der Mosh'Ogg"}, {"Schamane der Mosh'Ogg"}}},
    [97453] = {n="Schönheitsschnitt", d="Tötet 6 fleischfressendes Unkraut südlich von Grom'gol und informiert dann Gemmils Mutter.", tgo={{"Fleischfressendes Unkraut"}}},
    [97485] = {n="Traditionen von Thunder Bluff", d="Kauft ein Kräuterbündel von Nida der Kräuterkundigen, ein Bündel Zedernzweige von Nata, der Verkäuferin für Verzauberkunstbedarf, und Sehnenfaden von Mahu, dem Verkäufer für Lederverarbeitungsbedarf, sowie Feuerstein und Zunder von Naal, dem Verkäufer für Kochbedarf.\nFügt die Gegenstände zusammen und streut das Räucherwerk von der Anhöhe der Jäger.", objs={"Räuchergefäß"}},
    [97530] = {n="Was die Dünenbrecher stahlen", d="Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris möchte, dass Ihr einen besonders glänzenden Armreif zurückbringt, der irgendwo beim Lager der Oger der Dünenbrecher verloren ging.", tgo={{"Oger der Dünenbrecher", "Vollstrecker der Dünenbrecher", "Ogermagier der Dünenbrecher", "Schläger der Dünenbrecher", "Hexenmeister der Dünenbrecher"}}},
    [97534] = {n="Ein schmutziges Geschäft", d="Quinn möchte, dass Ihr 7 Haufen Wüstenschutt sammelt und zu ihr nach Gadgetzan bringt."},
    [97539] = {n="Am seidenen Faden", d="Bringt 12 Stücke chirurgischer Spinnenseide zu Doktor Gregory Victor in Hammerfall, Arathihochland.", tgo={{"Ebenenkrabbler", "Riesiger Ebenenkrabbler"}}},
    [97558] = {n="Häute, Bälge, Membranen", d="Bringt Shelene Rhobart 8 Nachtsaugerflügelmembranen, 6 Schattenhundbälge und 3 Häute eines Murlocs der Finsterflossen.", tgo={{"Großer Nachtsauger", "Vampirnachtsauger"}, {"Altersschwacher Schattenhund", "Verfluchter Schattenhund"}, {"Schwaches Orakel der Finsterflossen", "Matschkrabbler der Finsterflossen"}}},
    [97908] = {n="Grundlagen des Zeltens: Kürschnerei", d="Geht nach Orgrimmar und sprecht mit Thuwd, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", tgo={{"Thuwd"}}},
    [97936] = {n="Grundlagen des Zeltens: Kürschnerei", d="Geht zum Dorf der Bloodhoof und sprecht mit Yonn Deepcut, um zu lernen, wie Ihr einen Lagergegenstand für Euren Beruf herstellt, nachdem Ihr Euer Geschick in Eurer Fertigkeit unter Beweis gestellt habt.", tgo={{"Yonn Deepcut"}}},
    [98024] = {n="Reise nach Crossroads", d="Meldet Euch bei Thork in Crossroads im Brachland."},
    [98069] = {n="Gestohlene Vorräte vom Freiwindposten", d="Bringt 8 gestohlene Vorräte vom Freiwindposten zu Jandia im Freiwindposten."},
    [98070] = {n="Ausgekreischt", d="Tötet 5 kreischende Harpyien, 5 kreischende Wildfedern und 5 kreischende Windruferinnen.", tgo={{"Kreischende Harpyie"}, {"Kreischende Wildfeder"}, {"Kreischende Windruferin"}}},
    [98093] = {n="Das Feld säubern", d="Sulhasa im südlichen Brachland möchte, dass Ihr 7 Sturmechsen und 7 Fleischreißerpirscher in der Gegend beseitigt, damit sie sicher von dem Baum herunterkommen kann.", tgo={{"Fleischreißerpirscher"}, {"Sturmechse"}}},
    [98094] = {n="Späherunterstützung", d="Hochexekutorin Darthalia möchte, dass Ihr Todespirscher Masoj südlich von Tarrens Mühle außerhalb von Dun Garok aktualisierte Befehle überbringt."},
    [98095] = {n="Nützliche Vorteile", d="Todespirscher Masoj möchte, dass Ihr drei Phiolen des Apothekariums auf Gipfeln rund um das Vorgebirge von Hillsbrad platziert und dann zu ihm zurückkehrt."},
    [98298] = {n="Arugals Torheit", d="Bringt 6 Worgenstückchen zu Dalar Dawnweaver am Grabmal.", tgo={{"Moonrage-Blutheuler"}}},
    [98299] = {n="Die Ausbreitung eindämmen", d="Tötet 5 kränkliche Flüchtlinge und 5 hagere Flüchtlinge für Dalar Dawnweaver am Grabmal.", tgo={{"Hagerer Flüchtling"}, {"Kränklicher Flüchtling"}}},
    [98340] = {n="Der große Katzengeist", d="Sprecht mit Dendrite Starblaze in Nighthaven in Moonglade."},
    [98341] = {n="Der Große windgetragene Katzengeist", d="Sucht den Avatar von Saeyleenan im südlichen Teil von Moonglade auf und lernt alles, was er Euch über die Natur der windgetragenen Katze mitzuteilen hat."},
